-- 101_exam_tactics_more_examples.sql
-- 24 Kasim 2026 kullanici geri bildirimi ("burada ki ornekler cok olmali, orneklerde neden o yapi/kelimeler kullanildi guzelce aciklanmali"):
-- exam_tactics tablosundaki TUM 94 satira (25 genel + 69 konu bazli) 2'ser YENI ornek ekler,
-- boylece her taktik 2 yerine 4 ornek icerir. Her yeni ornek, ayni house style'i korur
-- (Ingilizce sinav cumlesi + tetikleyici kelimeyi BUYUK HARFLE belirten Turkce gerekce) ve
-- mevcut 2 ornekten FARKLI senaryolar kullanir. examples_tr || ARRAY[...] ile mevcut diziye
-- EKLENIR, hicbir mevcut ornek silinmez/degistirilmez.

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u00a$"__________ his manager's repeated warnings about missing deadlines, he continued to submit his reports late every week." Boşluktan sonra "his manager's repeated warnings" bir İSİM ÖBEĞİ olduğu için doğru cevap "Despite"tir; "Although" bu konumda ancak özne+yüklemli bir cümlecik ("his manager repeatedly warned him") gelseydi doğru olurdu, bu yüzden burada seçilemez.$u00a$, $u00b$"The new policy was praised by almost every department, __________ a few managers argued it would increase their workload." İlk kısım genel bir onayı (almost every department) anlatırken boşluktan sonra KISMİ bir itiraz geliyor — bu yüzden beklenti kırıcı bir bağlaç gerekir. Doğru cevap "although"tur ("while" de kabul edilebilir); "because" (neden-sonuç) burada mantıksal bir çelişki yaratır çünkü itirazın nedenini değil, zıtlığını anlatmamız gerekir.$u00b$] WHERE id = '618e854c-8d19-4533-bc11-e9c7d908320f';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u01a$"It took the engineers several weeks to __________ why the bridge's central span was vibrating under light traffic." Burada karmaşık bir sorunun ÇÖZÜLMESİ/ANLAŞILMASI anlatıldığı için doğru cevap "figure out"tur; "in" parçacığı burada kullanılamaz çünkü cümle bir şeyin içine girmeyi değil, bir sorunun çözümünü anlatır.$u01a$, $u01b$"After moving to a new country, it took Elena almost a year to __________ with her colleagues at the new office." Burada bir GRUBA UYUM SAĞLAMA/KATILMA anlamı olduğu için doğru cevap "fit in"dir; "out" parçacığı burada DIŞARI/SONA ERME anlamına çekerdi ki bu cümlenin anlamıyla çelişir.$u01b$] WHERE id = '21a2099a-a2d0-418c-85d7-6db175c68878';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u02a$"Several unexplained ___ were reported by sailors in that region long before scientists offered an explanation." "phenomenon"un çoğulu "phenomena"dır ve cümledeki fiil çoğul ("were") olduğu için özneyle uyumlu olmalı → doğru cevap "phenomena"dır; "phenomenons" diye bir çoğul biçim yoktur.$u02a$, $u02b$"The dentist explained that most adult ___ eventually need some form of treatment." "tooth"un düzensiz çoğulu "teeth"tir; eski İngilizce kökenli isimler grubuna girer → doğru cevap "teeth"tir; "tooths" ya da "toothes" gibi -s ekiyle oluşturulmuş yanlış bir çoğul biçim sınavda çeldirici olarak kullanılır.$u02b$] WHERE id = '49093205-6e94-485c-98ff-b5e739afa6ae';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u03a$"The firefighter helped the terrified cat climb __________ the narrow ledge before carrying it to safety." Burada düz bir YÜZEYİN ÜSTÜNE çıkış anlatıldığı için doğru cevap "onto"dur; "into" kullanılsaydı kedinin kapalı bir alanın içine girdiği izlenimi verirdi, bir çıkıntının üstüne çıkmasını değil.$u03a$, $u03b$"The smugglers had carved a narrow passage __________ the mountain to move their goods undetected." Burada bir dağın İÇİNDEN GEÇİŞ anlatıldığı için doğru cevap "through"tur; "across" kullanılsaydı dağın yüzeyi boyunca, tepesinden bir geçiş anlatılırdı, içinden değil.$u03b$] WHERE id = '62301240-ee16-4fba-b163-1b86b30dd42d';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u04a$"I'm the only one who noticed the mistake in the report, __________?" "I am" cümlesinin etiketi düzensiz olarak "aren't I"dir ("amn't I" biçimi yoktur) → doğru cevap "aren't I"dir.$u04a$, $u04b$"There isn't enough evidence to support this theory yet, __________?" "there is/are" cümlelerinde özne yerine "there" tekrar edilir ve ana cümle olumsuz olduğu için etiket olumlu olmalı → doğru cevap "is there"dir; "isn't there" ya da özneyi "it" ile değiştiren bir cevap burada yanlıştır.$u04b$] WHERE id = '85b23833-51c5-4d21-bfa3-94cf0bc4d2c2';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u05a$"He has lived in this neighborhood __________ he was a small child." Boşluktan sonra "he was a small child" bir BAŞLANGIÇ NOKTASI olduğu için doğru cevap "since"tir; "for" gelseydi ardından "many years" gibi bir süre ifadesi gerekirdi.$u05a$, $u05b$"The two companies have been negotiating this merger __________ over eighteen months now." Boşluktan sonra "over eighteen months" açık bir SÜRE ifadesi olduğu için doğru cevap "for"dur; "since" kullanılsaydı "early last year" gibi bir başlangıç noktası gerekirdi, bir süre miktarıyla asla kullanılmaz.$u05b$] WHERE id = 'a3b441b0-06b5-49cc-a0b9-f7e2dd8cc3be';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u06a$"We used to meet every weekend, but __________ we've hardly had any time to see each other." Burada "son zamanlarda" anlamı gerektiği için doğru cevap "lately"dir; "late" (geç) kullanmak cümlenin anlamını bozar çünkü burada bir zaman dilimine değil bir sıklığa/son döneme gönderme yapılmaktadır.$u06a$, $u06b$"The children greeted their grandparents __________ at the airport after many months apart." Sıfat "happy" "-y" ile bittiği için zarf hali "-ily" ekiyle oluşur → doğru cevap "happily"dir; "happyly" diye bir yazım biçimi yoktur ve bu tür yazım hatası şıklarda sık bir çeldiricidir.$u06b$] WHERE id = 'd016ebd7-2893-41ad-aa84-a674ba8a078d';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u07a$"I __________ (know) the Johnsons for almost twenty years; they are like family to us." "know" kalıcı bir durum bildiren bir fiildir ve ASLA continuous formda kullanılmaz → doğru cevap "have known"tur; "have been knowing" bu tür durum fiilleriyle gramer açısından yanlıştır, süre ne kadar uzun olursa olsun değişmez.$u07a$, $u07b$"The technician __________ (replace) this same part three times already, yet the machine keeps breaking down." Cümlede "three times" ile SAYILABİLİR, tamamlanmış bir sonuç belirtildiği için doğru cevap "has replaced"tir; "has been replacing" kullanmak isteseydik cümlede bir sayı değil bir süre belirteci olması gerekirdi.$u07b$] WHERE id = 'e5805f0d-0b4e-4d24-a3c2-a5955110a81d';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u08a$"I can finish the painting by next week if you bring more canvas here," the artist said. → The artist said (that) she could finish the painting by the following week if I brought more canvas there. Hem "can→could" hem "next week→the following week" hem de "here→there" değişimi birden uygulanır çünkü reporting fiil (said) geçmiş zamandadır; koşul cümlesindeki "bring" de "brought" olarak bir basamak geriye kayar.$u08a$, $u08b$"Why did you leave the meeting early?" the manager asked her. → The manager asked her why she had left the meeting early. Soru kelimesi ("why") kalır ama "did...leave" yapısındaki "did" yardımcı fiili düşer ve "left" (past simple) bir basamak geriye kayarak "had left" (past perfect) olur, çünkü reporting fiil (asked) geçmiş zamandadır.$u08b$] WHERE id = '2ecfae88-18b4-48b2-a71d-debf689ef2bf';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u09a$"__________ the heavy rain, the marathon organizers decided not to cancel the event." Boşluktan sonra bir isim öbeği ("the heavy rain") geldiği için "Although" yanlıştır — doğru cevap "Despite" ya da "In spite of"tur; "However" ise bir bağlaç değil cümle zarfı olduğu için burada bir cümleciğin başına gelip onu diğerine doğrudan bağlayamaz, bu yüzden bu konumda hiçbir zaman doğru cevap olamaz.$u09a$, $u09b$"The negotiations collapsed at the last minute. __________, both sides agreed to resume talks the following month." Burada iki TAM cümle nokta ile ayrılmış, aralarında bir zıtlık var — bu "however"ın tam da kullanıldığı yapıdır (cümle zarfı olarak iki bağımsız cümleyi bağlar) → doğru cevap "However"dır; "Despite" ya da "Although" burada doğrudan kullanılamaz çünkü ikisi de bağımsız bir cümlenin başında tek başına duramaz, bir cümleciğe bağlanmaları gerekir.$u09b$] WHERE id = '8429f4f4-29d8-46d3-b405-25862bb60e54';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u010a$"The laptop (that) I bought last month has already started malfunctioning." "that" burada "bought"ın nesnesi konumunda ve virgülsüz (defining) bir cümlecik olduğu için atılabilir, iki hâli de doğrudur: "The laptop I bought last month..." ya da "The laptop that I bought last month..." her ikisi de kabul edilir.$u010a$, $u010b$"The scientist who discovered the vaccine was awarded a prestigious international prize." Burada "who" cümlenin öznesi konumundadır (ardından doğrudan "discovered" yüklemi gelir) → bu yüzden atılamaz: "The scientist discovered the vaccine was awarded..." şeklinde zamiri çıkarmak cümleyi anlamsız ve gramer açısından hatalı hale getirir.$u010b$] WHERE id = '6b3ef7d7-206f-48b3-8886-4129990035b8';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u10a$Bir sonraki cümle "This shift forced many companies to rethink their supply chains entirely." ile başlıyorsa, boşluktaki cümle büyük çaplı, köklü bir DEĞİŞİMİ ("this shift") tanımlamalı — ufak, günlük bir ayrıntıdan bahseden bir şık, referans kelimesinin büyüklüğüyle uyuşmadığı için elenir.$u10a$, $u10b$Bir sonraki cümle "However, critics argue that the plan overlooks smaller businesses." ile başlıyorsa, boşluktaki cümle planı OLUMLU bir çerçevede sunmalı — çünkü "however" önceki cümleyle tam ters yönde bir eleştiri getirecektir; boşlukta zaten olumsuz bir ton taşıyan bir şık bu zıtlığı sağlayamayacağı için elenir.$u10b$] WHERE id = 'f0d5f0e7-f466-4ae4-b5e3-28a515599cb0';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u11a$"She has decided to __________ her job to focus on her new business, even though it pays less." Burada bir işten VAZGEÇME anlamı olduğu için doğru cevap "give up"tır (tamamlama/bitirme anlamı taşıyan "up"); "give down" diye bir ifade yoktur.$u11a$, $u11b$"Please __________ your phone number so I don't forget it." Burada bir bilgiyi NOT ALMA anlamı olduğu için doğru cevap "write down"dır (kaydetme anlamı taşıyan "down"); "write up" farklı bir anlam taşır (resmi rapor hazırlamak), bu basit not alma eylemine uymaz.$u11b$] WHERE id = '24970b9d-ad2c-46a4-b57c-96942eaa01e7';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u12a$"Despite the heavy rain, the charity event turned out to be a __________ success." Boşluk "success" (isim) kelimesini nitelediği için doğru cevap sıfat olan "good"tur; "well" bir ismi niteleyemez, sadece istisnai sağlık anlamında sıfat olarak kullanılabilir ki burada sağlıkla ilgili bir bağlam yoktur.$u12a$, $u12b$"The negotiations went so __________ that both sides signed the agreement a day early." Boşluk "went" fiilini nitelediği için doğru cevap zarf olan "well"dir; "good" bir fiili nitelendiremeyeceği için yanlıştır.$u12b$] WHERE id = '4fb315b2-b67f-46ec-a1f7-7cfbb510c876';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u13a$"This time next month, I __________ (relax) on a beach in Antalya instead of sitting in this office." "this time next month" belirli bir anı işaret ediyor ve o anda tatilde olma eyleminin HALA SÜRECEĞİ anlatılıyor → doğru cevap future continuous "will be relaxing"tir.$u13a$, $u13b$"By the end of this year, the company __________ (open) three new branches in different cities." "by the end of this year" ifadesi, şubelerin açılma eyleminin o zamana kadar TAMAMLANMIŞ olacağını gösteriyor → doğru cevap future perfect "will have opened"tir.$u13b$] WHERE id = '786b77cd-08ea-48c7-9669-7591666dc259';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u14a$"I've already read this novel; do you have a more recent ___?" "novel" sayılabilen, tekil bir isim olduğu ve tekrar edilmemesi gerektiği için doğru cevap "one"dur.$u14a$, $u14b$"The blue curtains look old-fashioned; let's buy some new ___ instead." "curtains" çoğul olduğu için doğru cevap "ones"tur; tekil "one" burada gramer olarak uyumsuzdur.$u14b$] WHERE id = '8a5f28b6-b85d-468e-a81a-4d577ea3d36c';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u15a$"The airline only allows one piece of __________ per passenger on this flight." "luggage" Türkçede çoğul/sayılabilir gibi hissettirse de İngilizcede SAYILAMAZ bir isimdir, bu yüzden "a luggage" ya da "luggages" asla kullanılmaz; doğru kullanım bölücü ifade "a piece of luggage"dır, boşluğa sadece tekil "luggage" gelir.$u15a$, $u15b$"Have you heard the __________ about the merger? It's all over the office." "news" sonu -s ile bitmesine rağmen SAYILAMAZ bir isimdir ve her zaman tekil fiille kullanılır → doğru cevap "news"tir; "a news" ya da "news are" gibi kullanımlar kesinlikle yanlıştır.$u15b$] WHERE id = 'a7a0e88a-885d-4c2a-8b25-3f0ca7f4cc26';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u16a$"I really __________ apologize to her — I've been feeling guilty about what I said all week." Zorunluluk konuşmacının kendi vicdani hissinden, KİŞİSEL bir gereklilikten doğduğu için doğru cevap "must"tur; "have to" dışarıdan bir kural çağrıştıracağı için konuşmacının içsel pişmanlık tonunu tam yansıtmaz.$u16a$, $u16b$"Employees __________ wear safety helmets on the construction site at all times." Zorunluluk iş güvenliği mevzuatının DIŞARIDAN koyduğu bir kural olduğu için doğru cevap "have to"dur; kuralın kaynağı resmi bir otorite olduğundan bu bağlamda tercih edilen ifadedir.$u16b$] WHERE id = 'd35a6f81-754a-4637-b1b1-1b8ba08f3a53';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u17a$"It is __________ that the flight will be delayed due to the storm warning." Burada "be" fiilinden sonra bir SIFAT gerekir ve "likely" (muhtemel) tam olarak bu konumda kullanılan, -ly ile biten ama aslında sıfat olan bir kelimedir; bunu zarf sanmak hataya yol açar.$u17a$, $u17b$"Smoking is one of the most __________ habits a person can develop." Burada bir İSMİ ("habits") niteleyen bir sıfat gerekiyor ve "deadly" (öldürücü) -ly ile bitmesine rağmen zaten bir sıfattır; "deadlily" diye bir zarf yoktur.$u17b$] WHERE id = 'eaae34aa-c742-4953-9fc7-8761f01c71ad';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u18a$"They finally managed ___ (finish) the project despite the tight deadline." "manage" fiilinden sonra GELECEĞE yönelik bir niyet değil, zaten başarılmış somut bir sonucu anlattığı için to-infinitive alır → doğru cevap "to finish"tir, "manage" kesinlikle -ing almaz.$u18a$, $u18b$"I'll never forget ___ (see) the northern lights for the first time — it was breathtaking." Burada GEÇMİŞTE yaşanmış bir anıyı hatırlamak anlatıldığı için doğru cevap "seeing"dir; "forget to do" (yapılacak bir görevi unutmak) burada anlamca uymaz çünkü cümle geçmiş bir deneyimden bahsediyor.$u18b$] WHERE id = '319a9471-5479-4d76-adb7-da73d58a2129';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u19a$"You really shouldn't skip breakfast every day," the doctor said. → The doctor advised him not to skip breakfast every day. "Advise" kalıbı "kişi + to + fiil" alır ve olumsuzlukta "not" doğrudan "to"dan önce gelir; "advised to not skip" bu kalıba uymadığı için yanlıştır.$u19a$, $u19b$"I didn't take the money, I promise," he said. → He denied that he had taken the money. "Deny" kişi almaz ve "that + özne + yüklem" kalıbını kullanır; "denied to take the money" gibi bir yapı bu fiilin kalıbına uymadığı için YDS'de klasik bir tuzaktır.$u19b$] WHERE id = 'bed5059e-31fb-4397-863e-61db3cb37dc3';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u110a$"___ I use the restroom before we start the meeting?" Burada resmi bir ortamda izin isteme söz konusu → doğru cevap "May" (ya da gündelik dilde "Can"); "Could" burada da kabul edilebilir bir rica tonu katar ama "May" resmi izin istemenin en klasik işaretidir.$u110a$, $u110b$"___ you hold the door for me? My hands are full." Burada bir izin değil, kibar bir yardım RİCASI söz konusu → doğru cevap "Could" (ya da "Would"); "May" burada garip kaçar çünkü karşı taraftan bir eylem yapmasını rica ediyoruz, izin istemiyoruz.$u110b$] WHERE id = 'dac7e7b7-d658-48cf-818f-7a4b6c25a582';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u20a$"Had the committee approved the budget earlier, the project would not have been delayed." Yüklemler önce belirlenir: "Had approved" (past perfect, şart anlamı taşıyan devrik yapı) ve "would not have been delayed" (üçüncü tip şartın sonuç kısmı, edilgen+perfect). Türkçe şıklarda "onaylamış olsaydı...gecikmeyecekti" yapısını tam karşılamayan, zamanı düz geçmişe indirgeyen veya edilgenliği atlayan şıklar elenir.$u20a$, $u20b$"Yetkililer, köprünün önümüzdeki ay yeniden açılacağını duyurdu." Önce Türkçe yüklemin zamanı ve çatısı belirlenir: "duyurdu" (düz geçmiş, aktif), "açılacağını" (gelecek zaman + edilgen bir isim-fiil yapısı, -ıl eki). İngilizce şıklarda "announced" (aktif, geçmiş) ile "will be reopened" (edilgen, gelecek) ikilisini birebir karşılamayan — köprüyü aktif çatıyla açan ya da zamanı geçmişe çeviren — şıklar yanlıştır.$u20b$] WHERE id = 'e40293c6-8d1c-4fd2-aac0-531a6c8d36c5';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u21a$"We've already decided — we __________ (rent) a car for the whole trip instead of relying on public transport." "already decided" ifadesi eylemin konuşmadan ÖNCE planlandığını gösteriyor → doğru cevap "are going to rent"tir; "will rent" burada o anda verilen bir karar izlenimi yaratır ve "already decided" ile çelişir.$u21a$, $u21b$"Can someone answer the door? — Sure, I __________ (get) it." Bu, konuşma ANINDA alınan SPONTANE bir karar/teklif olduğu için doğru cevap "will get"tir; "am going to get" burada önceden kurulmuş bir plan izlenimi verir ki bu, anlık bir teklife uymaz.$u21b$] WHERE id = '2725b7bc-7144-4958-a14d-5552d3ed7760';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u22a$"__________ of my two brothers is interested in sports; they both prefer reading." İki kardeşten bahsediliyor ve HİÇBİRİNİN spor ile ilgilenmediği (olumsuz bir durum) anlatılıyor → doğru cevap "Neither"dır (tekil fiil "is" ile uyumlu); "either" tek başına bu olumsuz anlamı taşıyamaz, "not... either" şeklinde kullanılması gerekirdi.$u22a$, $u22b$"You can park on __________ side of the street; parking is free on both this week." İki taraftan bahsediliyor ve HERHANGİ BİRİNİN seçilebileceği anlatılıyor → doğru cevap "either"dir; "all" burada yanlıştır çünkü "all" ikiden fazla seçenek için kullanılır, sadece iki taraf söz konusuyken uygun değildir.$u22b$] WHERE id = '51723fdd-1abf-48dc-b539-15d55f1adae7';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u23a$"The lecture was __________ interesting, though I expected it to be more engaging given the professor's reputation." Cümledeki "though" ve hafif hayal kırıklığı tonu, beklenenden AZ bir yoğunluğu işaret ediyor, nötr bir orta derece anlatılıyor → doğru cevap "fairly"dir; "rather" burada daha güçlü bir olumsuz vurgu taşırdı ve cümledeki ölçülü tona "fairly" kadar doğal uymaz.$u23a$, $u23b$"I'm __________ certain that she already knows about the surprise party; she's been acting strangely all week." "certain" derecelenemeyen (mutlak) bir sıfattır, bu yüzden buradaki "quite" "oldukça" değil "neredeyse tamamen" anlamına gelir → doğru cevap "quite"tır; "rather" mutlak sıfatlarla doğal bir şekilde bir araya gelmediği için burada tercih edilmez.$u23b$] WHERE id = '7ea32cae-1d01-4bf9-b7c2-32d8f887396c';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u24a$"I'll keep practicing the violin until I __________ (master) this piece completely." "until" ile kurulan zaman cümleciğinde gelecek bir eylemden bahsedilse bile "will" kullanılmaz, Present Simple yeterlidir → doğru cevap "master"dır; "will master" bu kalıpta klasik bir tuzaktır.$u24a$, $u24b$"While you __________ (wait) for the bus, I'll run into the pharmacy to pick up my prescription." "while" ile kurulan ve ana cümledeki eylemle EŞZAMANLI süren bir eylem anlatıldığı için doğru cevap Present Continuous "are waiting"tir; "will wait" burada da zaman cümleciğinde "will" kullanılamayacağı kuralını ihlal eder.$u24b$] WHERE id = '91bc4f15-b79e-4eeb-9fde-90054f934f0e';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u25a$"The union insisted ___ a full investigation before any employees were dismissed." "insist on" kalıbındaki "on" bir edattır, ardından -ing gelir → doğru cevap "on conducting"dir; "to conduct" burada edat kuralını ihlal ettiği için yanlıştır.$u25a$, $u25b$"You can't complete this assignment without ___ the instructions carefully first." "without" bir edattır ve ardından -ing gelir → doğru cevap "reading"dir; "to read" ya da yalın "read" burada edattan sonra kesinlikle gelemez.$u25b$] WHERE id = 'c0d0bfe9-a8ba-4b33-a45a-b81cd7863d84';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u26a$"I can't join you for lunch on Monday — I __________ a client in Ankara that whole day." Belirli bir gün ve önceden ayarlanmış bir iş randevusu anlatıldığı için doğru cevap present continuous "am meeting"tir; "will meet" burada o anda alınan bir karar izlenimi verir, önceden ayarlanmış somut bir plana uymaz.$u26a$, $u26b$"Judging by how dark those clouds look, I __________ we'll need umbrellas later today." Burada somut bir düzenleme değil, gözlemden yola çıkan kişisel bir TAHMİN/görüş anlatıldığı için doğru cevap "think" fiiliyle kurulan "will need"dir; "am needing" durum fiili olan "need"in -ing alamayacağı için zaten yanlıştır, present continuous bu cümlede hiç uygun değildir.$u26b$] WHERE id = 'd3da5634-4746-4bc3-9ef4-dfc109cbde5d';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u27a$"From my window, I watched the workers __________ (build) the entire fence over the course of the afternoon." Cümlede "over the course of the afternoon" ifadesi eylemin BAŞINDAN SONUNA KADAR tamamının izlendiğini gösteriyor → doğru cevap bare infinitive "build"dir.$u27a$, $u27b$"I noticed smoke __________ (come) from the kitchen window as I walked past the building." Burada sadece yoldan geçerken kısa bir an için fark edilen, SÜREN bir eylem anlatılıyor, başlangıcı veya sonu bilinmiyor → doğru cevap -ing formu "coming"dir.$u27b$] WHERE id = 'f0c19f77-f6dc-4f7f-8e5d-3afd95015fa5';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u28a$"The author, ___ latest novel won several international awards, will be giving a talk at the university next week." Boşluktan sonra "latest novel" (bir isim) gelmesi AİTLİK bildiren bir zamir gerektiğini gösterir → doğru cevap "whose"tur; "who" veya "which" burada aitlik anlamı taşımadığı için yanlıştır.$u28a$, $u28b$"This is the laboratory ___ the vaccine was first developed and tested." Boşluktan sonra tam bir özne+yüklem ("the vaccine was first developed") geliyor ve anlam bir YERE işaret ediyor → doğru cevap "where"dir; "which" kullanılacaksa önüne mutlaka bir edat gelmesi gerekirdi ("in which"), yalın "which" burada yetersiz kalır.$u28b$] WHERE id = '7c22d868-2e33-4369-b962-0417ead3b258';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u29a$"The patient ___ operated on immediately, or his condition will worsen rapidly." Cümle bir ZORUNLULUK ve UYARI anlatıyor, perfect bir çıkarım değil → doğru cevap modal+edilgen "must be"dir; "must have been" burada yanlıştır çünkü ameliyat henüz gerçekleşmemiş, gelecekte yapılması gereken bir eylemdir.$u29a$, $u29b$"Given the extent of the damage, the building ___ evacuated well before the storm hit." Burada geçmişe dönük bir ÇIKARIM (muhtemelen tahliye edilmişti) ve edilgenlik bir arada gerekiyor → doğru cevap "must have been"dir (modal+have been+V3); "must be" burada yanlıştır çünkü cümle geçmişte tamamlanmış bir duruma dair bir çıkarım yapıyor, şimdiki bir zorunluluğu değil.$u29b$] WHERE id = 'd1f055e1-616e-4792-9199-6a35038852ec';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u210a$"If they ___ (invest) in better equipment years ago, their factory would be far more productive today." Geçmişteki bir karar (yatırım yapmadılar) ŞİMDİKİ bir sonucu (düşük verimlilik) etkilediği için doğru cevap "had invested"tir (if + past perfect); sonuç kısmındaki "today" kelimesi şimdiki zamana işaret ettiği için "would be" (would + yalın fiil) kullanılmıştır, "would have been" değil.$u210a$, $u210b$"If he ___ (not/be) such a stubborn person, he would have accepted their help when the accident happened." Kişilik özelliği (inatçılık) ŞİMDİKİ zamanda devam eden genel bir durum, ama sonuç ("yardımı kabul etmedi") GEÇMİŞTE gerçekleşmiş bir olay → doğru cevap "weren't" (if + past simple)tir; sonuç kısmında zaten doğru şekilde "would have accepted" (would have + V3) kullanılmıştır.$u210b$] WHERE id = 'fd48f9bb-1483-4aef-92f6-f6a1cfd26945';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u30a$"To everyone's surprise, the young lawyer had __________ won two major cases before her thirtieth birthday." Cümle olumlu ve beklenenden önce gerçekleşmiş bir başarıyı vurguluyor, kelime yardımcı fiil ile ana fiil ARASINA yerleşiyor → doğru cevap "already"dir; "yet" bu konumda kullanılmaz, çünkü "yet" sadece olumsuz/soru cümlelerinin SONUNDA yer alır.$u30a$, $u30b$"Despite months of negotiations, the two companies __________ haven't reached a final agreement on the merger." Durum hâlâ devam ettiği (anlaşma sağlanamamış) ve kelime yardımcı fiilden ÖNCE konumlandığı için doğru cevap "still"dir; "yet" burada yanlıştır çünkü "yet" cümle ortasında değil, cümle SONUNDA kullanılabilirdi.$u30b$] WHERE id = '01161703-c7c9-4589-9c08-9dd5924ffce8';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u31a$A: "He can't attend tomorrow's meeting because of a scheduling conflict." B: "___ can I." Önceki cümle OLUMSUZ bir modal ("can't") içerdiği için katılma ifadesi "neither" ile kurulur → doğru cevap "Neither"dır; "So can I" burada anlam çelişkisi yaratır çünkü "so" sadece olumlu cümlelerden sonra kullanılır.$u31a$, $u31b$A: "I'm absolutely exhausted after today's twelve-hour shift." B: "___ am I." Önceki cümle OLUMLU ve yardımcı fiil olarak "be" fiilinin bir hali ("am") kullanıldığı için katılma ifadesinde de AYNI yardımcı fiil tekrarlanır → doğru cevap "So"dur; "Neither" kullanmak hem anlam çelişkisi yaratır hem de yanlış bir yardımcı fiil seçimine ("do" gibi) yol açabilirdi.$u31b$] WHERE id = '2fb1724d-fecb-4b93-a1f9-0ea8a48a9140';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u32a$"The old barn was completely destroyed ___ a powerful tornado that swept through the region." Boşluktan sonra CANLI bir doğa gücü (fail) geldiği için doğru cevap "by"dır; "with" burada yanlıştır çünkü tornado bir araç değil, eylemi gerçekleştiren faildir.$u32a$, $u32b$"The fragile artifact was carefully cleaned ___ a soft-bristled brush before being placed in the display case." Boşluktan sonra CANSIZ bir alet (fırça) geldiği ve bu alet temizlik için kullanılan ARAÇ olduğu için doğru cevap "with"tir; "by" burada yanlıştır çünkü fırça bir fail değildir.$u32b$] WHERE id = '5314db6b-bdb0-464f-b2e3-d11c21f7e4b1';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u33a$"Her brand-new trousers __________ (be) unfortunately a size too small, so she had to exchange them." "trousers" SADECE ÇOĞUL formda bulunan bir isimdir ve her zaman çoğul fiil alır → doğru cevap "are"dir, tekil "is" asla kullanılmaz.$u33a$, $u33b$"The jury __________ (be) deeply divided, with some members pushing for a guilty verdict and others for acquittal." "with some members... others..." ifadesi üyelerin AYRI AYRI davrandığını vurguluyor → doğru cevap "are"dir; bütün olarak hareket eden bir jüriden bahsedilseydi ("the jury is deliberating"), tekil fiil doğru olurdu.$u33b$] WHERE id = '80b5c1aa-ce11-45f6-8040-c04aae11221f';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u34a$"The strict new company policy doesn't allow employees ___ personal calls during working hours." "allow" fiili de nesne ("employees") + to-infinitive kalıbı ister → doğru cevap "to make"dir; nesnesiz "making" burada yanlıştır.$u34a$, $u34b$"The nutritionist recommended ___ more vegetables instead of relying on supplements." "recommend" fiili nesne+to-infinitive kalıbına UYMADIĞI için ardından -ing gelir → doğru cevap "eating"dir; "people to eat" gibi bir yapı kurmak burada yaygın bir hata olurdu.$u34b$] WHERE id = '97810547-d76e-4236-b591-0502859fd43c';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u35a$"He always tries to avoid ___ about his personal life during job interviews." "avoid" fiilinden sonra kesinlikle gerund gelir, to-infinitive asla gelmez → doğru cevap "talking"dir.$u35a$, $u35b$"___ the piano for several hours every day eventually paid off when she won the national competition." Cümlenin öznesi konumunda bir -ing yapısı gerekir ve gerund öbeği her zaman tekil kabul edilir → doğru cevap "Practicing"dir.$u35b$] WHERE id = 'c205e679-9ba6-4838-9fb8-3679b708acb3';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u36a$"Despite strong objections from her colleagues, she insisted ___ handling the negotiations herself." "insist" fiilinden sonra sabit olarak "on" edatı gelir → doğru cevap "on"dur.$u36a$, $u36b$"After weeks of persuasion, he finally succeeded ___ convincing the board to approve the budget increase." "succeed" fiilinden sonra sabit olarak "in" edatı gelir → doğru cevap "in"dir; Türkçe "başarmak" kelimesinden yola çıkarak "at" ya da "to" seçmek yaygın bir hata olur.$u36b$] WHERE id = 'd47ebfcc-b547-4ce1-89aa-3cc171d702aa';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u37a$"I was just ___ call you when your message arrived, what a coincidence!" "just" kelimesi "about to" yapısını pekiştiren tipik bir sinyal kelimedir, çok yakın bir anı vurgular → doğru cevap "about to"dur.$u37a$, $u37b$"Look at those dark clouds gathering overhead — it ___ to pour down any minute now." Konuşma anından hemen sonra, neredeyse o anda gerçekleşecek somut bir gözleme dayalı tahmin var → doğru cevap "is about"tır (is about to); "will" burada da kabul edilebilir bir tahmin olsa da "about to" yapısı buradaki ÂNİLİK vurgusunu daha güçlü karşılar.$u37b$] WHERE id = 'f1049e51-eb81-4d4f-a8f7-24e065ec1639';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u38a$"If you __________ (mix) red and blue paint, you get purple." Genel, değişmeyen bir gerçek (renk karışımı) anlatıldığı için Tip 0 kullanılır, doğru cevap "mix"tir (present simple).$u38a$, $u38b$"If the company __________ (not/invest) in new technology soon, it will struggle to remain competitive." Gelecekte gerçekleşmesi mümkün bir durum anlatıldığı için Tip 1 kullanılır, if cümleciğinde present simple'ın olumsuz hali gerekir → doğru cevap "doesn't invest"tir; "won't invest" if cümleciğinde asla kullanılmaz.$u38b$] WHERE id = '8e4cad68-ff49-4324-a2ca-676cc5d8f832';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u39a$"Passengers ___ fasten their seatbelts whenever the illuminated sign requires it; it's a strict airline regulation." Zorunluluk havayolunun koyduğu DIŞARIDAN bir kuraldan geldiği için doğru cevap "have to"dur.$u39a$, $u39b$"You ___ apologize for the delay — it was completely out of your control and nobody is blaming you." Burada yapılmasının GEREKMEDİĞİ ama serbest olduğu bir durum anlatılıyor → doğru cevap "don't have to"dur; "must not" kullanmak burada bir YASAK anlamı katar ki bu cümlenin bağlamıyla çelişir.$u39b$] WHERE id = 'e8cab074-60e8-43c1-b973-2bb9273e1c43';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u310a$"___ finished all her assignments early, she decided to spend the rest of the evening reading a novel." Ana eylemden (karar verme) ÖNCE tamamlanmış bir eylemi vurgulamak için "having + V3" (perfect participle) kullanılır → doğru cevap "Having finished"dir.$u310a$, $u310b$"The documents ___ by the committee last week are now available for public review." Fiil EDİLGEN olduğu için ("which were approved" ifadesinin kısaltılmış hali) geriye sadece past participle kalır → doğru cevap "approved"tur (V3); "approving" (aktif -ing) burada yanlıştır çünkü belgeler onaylamıyor, onaylanıyor.$u310b$] WHERE id = 'c7009f21-5574-444e-98dd-f1a114d2201d';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u40a$"The negotiations __________ when both sides refused to compromise on the price." Cümlede tarafların uzlaşmayı REDDETMESİ, görüşmelerin BAŞARISIZLIKLA SONA ERDİĞİNİ gösteriyor → doğru cevap "broke down"dır (çökmek/bozulmak); "broke up" (ayrılmak, genellikle ilişkiler için) ya da "broke out" (aniden başlamak, örn. savaş) parçacık farklı olduğu için tamamen yanlış bir anlam verir.$u40a$, $u40b$"After the scandal, the CEO was forced to __________ from his position." Skandaldan sonra bir yöneticinin GÖREVİNİ BIRAKMAYA ZORLANDIĞI anlatılıyor → doğru cevap "step down"dır; "step up" (bir göreve adım atmak/sorumluluk almak) parçacığın yön zıtlığı yüzünden tam tersi bir anlam taşır ve burada yanlıştır.$u40b$] WHERE id = '04b7a35d-06c1-4a16-bab7-0190185e82b0';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u41a$"The teacher suggested that the students __________ (try/solve) the problem using a different method before giving up." Burada farklı bir YÖNTEMİ DENEME/TEST ETME anlamı olduğu için doğru cevap "try solving"dir (-ing); "try to solve" kullanılsaydı anlam 'çözmeye çalışmak, başarmaya uğraşmak' olur ki bu da cümledeki 'farklı bir yöntem dene' önerisiyle tam örtüşmez.$u41a$, $u41b$"He finally __________ (stop/argue) with his neighbor after years of conflict." Yıllar süren bir eylemin SONA ERDİRİLMESİ anlatıldığı için doğru cevap "stopped arguing"dir (-ing, bir eylemi bırakmak); "stopped to argue" kullanılsaydı anlam 'tartışmak için durdu' gibi tuhaf bir amaç cümlesine dönüşürdü, metnin bağlamıyla çelişirdi.$u41b$] WHERE id = '33a90a12-792a-4987-8ef9-fe6d0ebf1b0e';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u42a$"The new bridge is not __________ the old one, which could handle much heavier loads." Olumsuz bir eşitlik karşılaştırması kuruluyor ve araya giren sıfat YALIN kalmalı → doğru cevap "as strong as"tır; "as stronger as" seçeneği "as...as" yapısı içinde üstünlük eki ("-er") barındırdığı için kesinlikle yanlıştır.$u42a$, $u42b$"For many students, learning a new language can be __________ difficult __________ mastering a musical instrument." İki taraf da aynı gramatik yapıda (iki ayrı -ing öbeği) karşılaştırıldığı için yapı PARALELDİR ve boşluklara yalın sıfatla "as...as" gelir → doğru cevap "as ... as"tır; sıfat üstünlük eki alsaydı ("as more difficult as") hem paralellik hem de üstünlük-eki tuzağı yüzünden yanlış olurdu.$u42b$] WHERE id = '582b694d-306b-4cbc-86f0-f675f96716b0';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u43a$"__________ newspaper contained an in-depth analysis of the election results." "today" bir ZAMAN İFADESİ olduğu için CANSIZ olmasına rağmen istisnai olarak 's kullanılır → doğru cevap "Today's"tir; "The newspaper of today" gramer olarak doğru olsa da zaman ifadelerinde doğal ve beklenen tercih 's'dir.$u43a$, $u43b$"__________ opinions on the matter were surprisingly similar, even though they work in different departments." Burada iki kişinin AYRI AYRI görüşlerinden bahsedildiği ("different departments" ayrımı) için her isme kendi 's'i eklenir → doğru cevap "My manager's and my colleague's"tir; sadece sona tek bir 's eklemek ("my manager and colleague's") burada yanlış olur çünkü bu TEK bir ORTAK görüşe işaret eder, oysa burada ayrı görüşler karşılaştırılıyor.$u43b$] WHERE id = '80ed5209-f8ab-4520-a652-d047080314b7';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u44a$"There isn't __________ traffic on the highway today, so we should arrive on time." "traffic" sayılamayan bir isimdir ve cümle OLUMSUZ olduğu için doğru cevap "much"tır; "many" sadece sayılabilir çoğul isimlerle kullanılabilir, "traffic" gibi sayılamayan bir isimle asla kullanılmaz.$u44a$, $u44b$"He has __________ close friends in this city, which makes him feel quite isolated." "feel quite isolated" (yalıtılmış/yalnız hissetmek) OLUMSUZ bir sonuç belirttiği için doğru cevap, "a" olmadan kullanılan "few"dür (neredeyse hiç yok anlamında); eğer "a few" kullanılsaydı anlam "yeterince arkadaşı var" olur ve "isolated" hissiyle çelişirdi.$u44b$] WHERE id = '9e721636-b34f-49bc-9293-3cbf1d292aa6';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u45a$"The ceremony traditionally begins __________ noon and lasts for about two hours." "noon" (öğlen) noktasal, belirli bir AN olduğu için doğru cevap "at"tır; "in" ya da "on" burada yanlıştır çünkü bunlar daha geniş dönemler ya da günler için kullanılır.$u45a$, $u45b$"Many historians believe the tradition originated __________ the 1800s, though its exact date is disputed." "the 1800s" bir YÜZYIL/ON YILLIK dönemi belirttiği için geniş bir zaman dilimidir → doğru cevap "in"dir; "on" veya "at" burada yanlıştır çünkü bunlar sırasıyla gün/tarih ve noktasal anlar için kullanılır, bir yüzyıl gibi geniş bir dönem için uygun değildir.$u45b$] WHERE id = 'c375daa0-1000-4bd6-8340-0f15bf6270e1';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u46a$"Both of my __________ are coming to the wedding next month." "mother-in-law" tireli bir bileşik isim olduğu ve ASIL isim ilk kısımda ("mother") olduğu için çoğul eki ilk kelimeye eklenir → doğru cevap "mothers-in-law"dur; "mother-in-laws" bu istisnayı ihlal ettiği için yanlıştır.$u46a$, $u46b$"The company just signed a __________ contract with its biggest supplier." "five year" burada bir SAYI+İSİM yapısı olup "contract" isminden ÖNCE sıfat görevi gördüğü için tireli ve TEKİL kalmalıdır → doğru cevap "five-year"dir; "five-years" yanlıştır çünkü bu artık bir isim değil, bir sıfat öbeğidir.$u46b$] WHERE id = 'd583d6a3-4018-4b72-89a4-f93bf680c420';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u47a$"While she __________ (wait) for the bus, she __________ (notice) a familiar face in the crowd." Otobüsü bekleme eylemi arka planda SÜREN bir eylemdir → "was waiting"; tanıdık bir yüz fark etmesi ANİ ve kısa bir eylemdir → "noticed". Doğru cevap: "was waiting / noticed".$u47a$, $u47b$"Every summer when I was a child, we __________ (spend) our holidays at my grandparents' farm." "Every summer" TEKRARLANAN bir alışkanlık belirttiği için doğru cevap "spent" (ya da "used to spend")tir; "were spending" (past continuous) burada yanlıştır çünkü arka planda süren tek bir eylem değil, yıllarca tekrarlanan bir alışkanlık anlatılıyor.$u47b$] WHERE id = 'f24cf90b-d976-4f7a-a3c4-24c2488a225b';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u48a$"I __________ (already/finish) my homework, so I can go out and play now." "already" present perfect'in klasik işaretçisi olduğu için doğru cevap "have already finished"tir; şimdiki sonuca (dışarı çıkabilme) bağlanan bir geçmiş eylem anlatıldığı için past simple ("finished") burada yetersiz kalır.$u48a$, $u48b$"They __________ (get) married exactly ten years ago, and they still live in the same house." "ago" KESİN bir geçmiş zaman belirteci olduğu ve ASLA present perfect ile kullanılmadığı için doğru cevap past simple olan "got married"dır; "have gotten married" burada her zaman yanlıştır çünkü "ago" varken cevap otomatik olarak past simple'a kilitlenir.$u48b$] WHERE id = '9e2c5ca8-24fe-440f-8a63-e336634786ec';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u49a$"If I __________ (have) wings, I would fly to every corner of the world." Cümlenin ana kısmında zaten "would fly" bulunduğu ve şimdiki zamanda gerçek olmayan hayali bir durum (kanadı yok) anlatıldığı için if cümleciğinde doğru cevap past simple olan "had"tir; "have" ya da "will have" kullanmak bu hayali/gerçek-dışı anlamı bozar.$u49a$, $u49b$"If the company __________ (be) more flexible with remote work, more employees would stay long-term." Özne "the company" (it) olmasına rağmen, "be" fiili if cümleciğinde Tip 2'de her özneyle "were" ister → doğru cevap "were"dir, "was" değil; bu kural özne insan olmasa bile değişmez.$u49b$] WHERE id = 'fddda164-3aeb-4c84-966a-a662a6df7c6e';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u50a$"__________ Nile is widely regarded as __________ longest river on the African continent." "Nile" özel bir nehir adı olduğu için her zaman "the" alır (the Nile); "longest" ise bir ÜSTÜNLÜK sıfatı olduğundan ikinci boşlukta da "the" zorunludur — üstünlük sıfatından önce "the"yi atlamak YDS'nin en sık tekrarlanan tuzaklarından biridir.$u50a$, $u50b$"Dogs cannot digest chocolate properly, but __________ dogs that live in this shelter are examined by a vet every week." İlk kısımda "Dogs" çoğul isim bir KATEGORİYİ bütün olarak temsil ettiği için artikelsiz kullanılır; ikinci kısımda "that live in this shelter" ilgi cümleciği köpekleri BELİRLİ bir gruba indirgediği için doğru cevap "the"dir.$u50b$] WHERE id = '05b7dbb8-ba5f-4149-93dc-939860916a8c';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u51a$"Since switching to a new diet, he has felt __________ (good) than he did last year, but his doctor says his cholesterol levels are still __________ (bad) than the recommended range." "than" kelimesi her iki boşlukta da KARŞILAŞTIRMA formunu tetikler; "good" sıfatının düzensiz hali "better"dir ("gooder"/"more good" yanlıştır), "bad" sıfatının düzensiz hali ise "worse"tür ("more bad"/"badder" yanlıştır).$u51a$, $u51b$"The sooner you submit your application, __________ your chances of receiving the scholarship." Cümle "the + comparative..., the + comparative..." kalıbıdır (iki şeyin birlikte değiştiğini anlatır) → doğru cevap "the higher"dir; "higher" tek başına ya da "more high" bu kalıpta yanlıştır, ikinci tarafın da mutlaka "the" ile başlaması gerekir.$u51b$] WHERE id = '36f0d9db-0f6c-4b8a-8139-4569ec608f30';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u52a$"It took Maria almost a year, but she eventually __________ the long commute to her new job across the city." Burada zamanla bir duruma ALIŞMA SÜRECİ anlatıldığı için doğru cevap "got used to"dur (get used to + isim); "used to" burada anlamca uymaz çünkü cümle bir sürecin SONUNDA alışmayı anlatır, geçmişte bırakılan bir alışkanlığı değil.$u52a$, $u52b$"Twenty years ago, my father __________ (ride) his bicycle to work every day; these days, though retired, he says he __________ (wake) up at 5 a.m. because of that old routine." İlk boşlukta geçmişte yapılıp artık (emekli olduğu için) yapılmayan bir alışkanlık anlatıldığından doğru cevap "used to ride"dır; ikinci boşlukta hâlâ ŞU ANDA o saatte uyanmaya ALIŞKIN OLMA durumu anlatıldığı için doğru cevap "is used to waking"tir (be used to + -ing), "used to wake" değildir çünkü bu alışkanlık hâlâ sürmektedir, bırakılmamıştır.$u52b$] WHERE id = '58ab2f97-23f2-4b37-b2fa-da2df95604b6';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u53a$"After hearing the __________ news about the merger, all the employees felt completely __________ about their job security." "news" duyguyu YARATAN kaynak olduğu için -ing hali ("shocking") doğru olur; "employees" ise bu haberden ETKİLENEN kişiler olduğu için -ed hali ("shocked") doğru olur.$u53a$, $u53b$"__________ chair had been in the family for three generations before it was finally restored." Doğru sıralama görüş (beautiful) → yaş (antique) → köken (French) → malzeme (wooden) şeklindedir, yani doğru cevap "A beautiful antique French wooden" dizilimidir; malzemeyi en başa alıp "A wooden antique French beautiful chair" demek İngilizcede doğal kabul edilmeyen bir sıralama oluşturur.$u53b$] WHERE id = '816a2d8f-fdde-4816-affe-633fddb74d56';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u54a$"The new policy will not take effect ___ all departments have completed the required training." "will not take effect" ifadesi "not...until" kalıbının bir parçasıdır ve politika o ana KADAR yürürlüğe girmeyecek, ancak ondan SONRA girecek anlamını taşır → doğru cevap "until"dür; "by" kullanılsaydı tam tersi bir beklenti (en geç o tarihte yürürlükte olması) yaratırdı.$u54a$, $u54b$"The construction company promised that the new bridge would be completed ___ the end of the year, although the surrounding roadworks might continue a little longer." Köprünün belirli bir tarihe kadar TAMAMLANMIŞ olması beklendiği (bir teslim tarihi/deadline mantığı) için doğru cevap "by"dır; yol çalışmalarının SÜRMESİ ayrı, süreklilik bildiren bir durumdur ve orada "until" kullanılması gerekirdi.$u54b$] WHERE id = '9ef40305-637c-4dcb-befa-b20d816a3be8';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u55a$"Even though it was freezing outside, he refused to __________ his jacket before stepping out the door." Burada bir GİYSİYİ üzerine koyma/giyme eylemi anlatıldığı için doğru cevap "put on"dur; "take off" (çıkarmak) tam ters bir anlam ifade eder ve "before stepping out" (dışarı çıkmadan önce) bağlamıyla çelişir.$u55a$, $u55b$"Please remember to __________ all the lights and the air conditioner before leaving the office tonight." "lights" ve "air conditioner" birer CİHAZ olduğu ve cümle bu cihazların DURDURULMASINI/KAPATILMASINI anlattığı için doğru cevap "turn off"tur; "turn on" (açmak) burada anlam olarak tam tersini ifade eder.$u55b$] WHERE id = 'c477b842-983a-4a45-847d-1d7db0d30e83';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u56a$"She performed the complicated dance routine __________ in front of thousands of spectators." Boşluk "performed" (fiil) eylemini nitelediği için bir ZARF gerekir → doğru cevap "gracefully"dir; "graceful" (sıfat) ya da "grace" (isim) bir fiili nitelendiremediği için burada kullanılamaz.$u56a$, $u56b$"Despite the tight deadline, the team decided to __________ every effort to deliver the project on time." İngilizcede "effort" kelimesiyle doğal eşleşen fiil "make"tir ("make an effort") — "do an effort" bir gramer hatası değil ama YERLEŞİK olmayan bir ifadedir, bu yüzden collocation sorularında hangi fiilin hangi isimle ALIŞILAGELMİŞ şekilde kullanıldığına bakmak gerekir.$u56b$] WHERE id = 'd9a28662-cb55-4ccc-8ae0-139f902f12b0';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u57a$"__________ Pacific Ocean is __________ largest ocean on Earth, covering nearly a third of the planet's surface." "Pacific Ocean" okyanus adı sabit coğrafi isimlerden biri olduğu için her zaman "the" alır; "largest" ise bir ÜSTÜNLÜK sıfatı olduğundan ikinci boşlukta da "the" zorunludur.$u57a$, $u57b$"__________ cars that were recalled last month had a faulty braking system, although __________ cars in general remain one of the safest forms of transport." İlk boşlukta "that were recalled last month" ilgi cümleciği belirli bir araba grubunu işaret ettiği için doğru cevap "The"dir; ikinci boşlukta "cars in general" ifadesiyle zaten GENEL bir kategoriden bahsedildiği açıkça belirtildiği için artikel kullanılmaz.$u57b$] WHERE id = 'f30e1a46-11df-47d9-848d-d4077d8b89f7';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u58a$"She says she has never been to Paris, but these photos were clearly taken right in front of the Eiffel Tower — she __________ be telling the truth." Kanıtlar (fotoğraflar) açık bir ÇELİŞKİYİ gösterdiği için olumsuz kesin bir çıkarım gerekir → doğru cevap "can't"tır; "must not" burada yanlıştır çünkü olumsuz kesinlik için İngilizce'de "can't/couldn't" kullanılır, "must not" farklı bir anlam (yasaklama) taşır.$u58a$, $u58b$"I __________ have brought my umbrella — the forecast clearly said it would rain all day, yet I left it at home and got soaked." Yağmur yağacağı önceden BİLİNDİĞİ halde şemsiye alınmaması bir PİŞMANLIK anlatıldığı için doğru cevap "should have brought"tur; "needn't have brought" yanlış olurdu çünkü o yapı GEREKSİZ YERE yapılmış bir eylemi anlatır, burada ise tam tersine yapılmamış ama yapılması gereken bir eylemden bahsedilmektedir.$u58b$] WHERE id = 'a3d3a6db-14a1-4e17-a046-0dc42781ce1e';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u59a$"The novel, __________ ending left many readers unsatisfied, became a surprise bestseller despite the criticism." "whose" sadece insanlar için değil, CANSIZ varlıklar için de kullanılabilir — burada "ending" romana AİTTİR, bu yüzden doğru cevap "whose"tur; bazı öğrenciler "whose"un sadece kişilerle kullanılabileceğini zannederek bu tür sorularda yanlış şıkka yönelir.$u59a$, $u59b$"The restaurant __________ we celebrated our anniversary last year has unfortunately closed down." "restaurant" bir YER ismi ve ardından öznesi tam olan bir cümle ("we celebrated...") geldiği için doğru cevap "where"dir; "which/that" kullanılsaydı cümlenin bir edatla ("...AT last year") tamamlanması gerekirdi.$u59b$] WHERE id = '31e0ff92-e2bb-492c-9a5c-f6db9135b75a';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u60a$"By the time we arrived at her house, she ___ to the dentist, so we had to wait nearly an hour for her to come back." Cümledeki "we had to wait... for her to come back" ifadesi kadının HÂLÂ GERİ DÖNMEMİŞ olduğunu gösteriyor → doğru cevap "had gone"dur (gone'un geçmiş zaman hali); "had been" burada yanlıştır çünkü "been" dönmüş olmayı ima eder, oysa burada kişi hâlâ yoktur.$u60a$, $u60b$"Have you ever ___ to Egypt? I've heard the pyramids are absolutely breathtaking." Cümledeki "ever" bir DENEYİM belirtecidir ve soruyu soran kişi karşısındakinin şu an burada olduğunu (yani gitmişse dönmüş olduğunu) varsayar → doğru cevap "been"dir; "gone" burada kullanılsaydı kişinin hâlâ Mısır'da olduğu gibi anlamsız bir çıkarım yapılırdı.$u60b$] WHERE id = '0c988772-ece0-4cc1-958a-f6dfaa659964';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u61a$"I don't know __________ from the station to the museum." Soru "I don't know" ifadesinin içine gömülü olduğu için devrik yapı kaybolur → doğru cevap "how far it is"tir, "how far is it" değildir çünkü bu bağımsız bir soru değildir.$u61a$, $u61b$"__________ at the conference yesterday that made such a strong impression on everyone?" Bu cümle bağımsız bir soru olduğu için normal devrik soru sırası geçerlidir → doğru cevap "Who spoke"tur; bu cümle "Do you remember..." gibi bir ifadenin içine gömülseydi ("Do you remember who spoke at the conference..."), devrik sıra kaybolurdu.$u61b$] WHERE id = '3b7fc300-cd9c-450b-aeaa-ea2e7e4f89b6';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u62a$"__________ the weather improves significantly by tomorrow morning, the outdoor concert will have to be cancelled." Cümle "eğer hava düzelmezse" anlamını taşıdığı için doğru cevap "Unless"tir; "If" kullanılsaydı fiilin olumsuz hâle getirilmesi gerekirdi ("If the weather doesn't improve").$u62a$, $u62b$"She always keeps a spare key with her neighbor __________ she accidentally locks herself out of the house." Burada gerçekleşmesi kesin olmayan bir duruma karşı ÖNCEDEN alınmış bir tedbir anlatıldığı için doğru cevap "in case"tir; "if" kullanılsaydı cümle mantıksız bir koşula dönüşürdü, çünkü anahtar zaten o an için değil, olası bir durum için bırakılmıştır.$u62b$] WHERE id = '5c0b08d8-1c54-4866-9168-71ce502d9610';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u63a$"___ of the two candidates has strengths that the other clearly lacks, which makes the decision difficult." Burada sadece İKİ adaydan bahsedildiği için, en az üç üye gerektiren "every" elenir → doğru cevap "Each"tir.$u63a$, $u63b$"___ employee in the department is required to complete the online safety course once a year, with no exceptions." Burada genel bir kural bölümdeki TÜM çalışanlara (üçten fazla kişiye) toptan uygulanıyor → doğru cevap "Every"dir; cümledeki "with no exceptions" ifadesi de bu toptan genellemeyi pekiştirir.$u63b$] WHERE id = '81d9ef24-7274-4259-8f54-3f2c763254e8';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u64a$"He realized he'd forgotten his umbrella at the office, so he had to go back and pick __________ up before the rain started." Boşluktaki nesne daha önce geçen "his umbrella"nın yerini tutan bir zamirdir (it) ve "pick up" ayrılabilir bir phrasal verb olduğu için zamir mutlaka araya girmelidir → doğru cevap "it" olup "pick it up" şeklinde kurulmalıdır.$u64a$, $u64b$"While her sister was away on business, she kindly offered to look __________ during the entire trip." "look after" (bakmak, ilgilenmek) ayrılamaz bir phrasal verb'dür, bu yüzden nesne zamir bile olsa grubun sonrasına gelir → doğru cevap "after them"dir; "look them after" şeklinde araya sokmak kesinlikle yanlıştır.$u64b$] WHERE id = 'a076c136-0045-4a67-989d-a162100d3b13';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u65a$"You ___ wait for me at the entrance; just go ahead and I'll catch up with you inside." Cümlede konuşanın karşı tarafı beklemesinin GEREKMEDİĞİNİ ama isterse bekleyebileceğini anlatan serbest bir izin tonu var → doğru cevap "needn't"tür; "mustn't" burada yanlıştır çünkü beklemek yasak değildir, sadece gereksizdir.$u65a$, $u65b$"Passengers ___ use their mobile phones during takeoff and landing, as it is a strict aviation safety regulation." Cümledeki "strict... regulation" ifadesi kesin bir yasağı belirtir → doğru cevap "mustn't"tür; "needn't" burada yanlıştır çünkü anlatılan şey bir gereksizlik değil, resmi bir yasaktır.$u65b$] WHERE id = 'c8de0b51-aa0d-4787-b9b2-97496126f796';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u66a$"__________ that the company's CEO is planning to step down before the end of this fiscal year." Kaynağı belirtilmeyen bir söylentinin "it" yapısıyla aktarılması gerektiği için doğru cevap "It is rumored"tur; bu yapıda "that" bağlacı kesinlikle korunmalıdır.$u66a$, $u66b$"The ancient manuscript __________ (write) by monks several centuries before the printing press was even invented." Yazılma eyleminin, bildirme anından ("inanılıyor") çok ÖNCE gerçekleşmiş ve tamamlanmış bir olay olduğu için doğru cevap "is believed to have been written"tir; sadece "is believed to be written" kullanmak, yazılmanın şu an gerçekleştiği gibi yanlış bir zaman ilişkisi kurardı.$u66b$] WHERE id = 'debef73d-0bf2-460e-abb8-e3fd0805d464';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u67a$"He kept nervously checking his phone ___ the entire presentation, which visibly annoyed the speaker." Boşluktan sonra bir isim öbeği ("the entire presentation") geldiği için doğru cevap "during"dir; "while" burada özne+yüklem içeren bir cümlecik gerektirdiği için yanlıştır.$u67a$, $u67b$"___ she was driving to work this morning, she suddenly remembered that she had left the oven on at home." Boşluktan sonra özne+yüklem içeren tam bir cümlecik ("she was driving...") geldiği için doğru cevap "While"dır; "during" burada bir isim öbeği gerektirdiği için kullanılamaz.$u67b$] WHERE id = 'f7de751d-c537-424b-89f6-da2086e3f3fe';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u68a$"The new regulation was expected to boost small businesses; __________, overall revenue in the sector actually declined in the following months." Beklenen olumlu sonuç (boost) ile gerçekleşen olumsuz durum (declined) arasında açık bir zıtlık var → doğru cevap "however"dür; "therefore" (sonuç bağlacı) burada iki cümle arasında bir neden-sonuç değil bir ÇELİŞKİ olduğu için yanlıştır.$u68a$, $u68b$"The hotel offers a complimentary breakfast every morning; __________, it provides a free shuttle service to and from the airport." İki cümle de otelin sunduğu olumlu hizmetleri PEKİŞTİREREK sıralıyor, aralarında zıtlık veya nedensellik yok → doğru cevap "moreover" ya da "in addition"dır; "as a result" burada bir sonuç ilişkisi olmadığı için yanlıştır.$u68b$] WHERE id = 'c004c79a-c766-436f-9e28-b4857404ef42';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u69a$"If she ___ (know) about the heavy traffic on the highway, she would have left the house a full hour earlier." Geçmişte gerçekleşmemiş bir durum (trafiği bilmedi, erken çıkmadı) anlatıldığı için doğru cevap "had known"dur, "would have known" if cümleciğinde asla kullanılmaz.$u69a$, $u69b$"If the team ___ (practice) more consistently throughout the season, they wouldn't have lost the championship match so badly." Geçmişte gerçekleşmemiş bir durum (düzenli çalışmadılar, kaybettiler) anlatıldığı için doğru cevap "had practiced"tir; bu yapı, if cümleciğinde "would have" kullanmanın neden kesinlikle yanlış olduğunu gösteren klasik bir YDS tuzağıdır.$u69b$] WHERE id = 'aa7cbd8a-9edf-4baf-af4f-7caba80af43f';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u70a$"__________ scientists agree that climate change is primarily driven by human activity." Boşluktan sonra ÇIPLAK bir çoğul isim ("scientists") geliyor, herhangi bir belirleyici (the/my/these) yok → doğru cevap "Most"tur; "Most of" burada yanlıştır çünkü "of"tan sonra mutlaka bir belirleyici gelmesi gerekir, çıplak bir isim gelemez.$u70a$, $u70b$"__________ my colleagues were surprised by the sudden announcement of the merger." Boşluktan sonra iyelik sıfatı + isim ("my colleagues") geldiği için doğru cevap "Most of"tur; sadece "Most" kullanmak için cümleden "my" kelimesinin çıkarılması gerekirdi, çünkü "most" doğrudan bir iyelik sıfatından önce gelemez.$u70b$] WHERE id = '15bc23dd-17f0-49c8-a390-74b369d7203a';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u71a$"The shipment arrived precisely __________ for the scheduled unloading at 6 a.m." Cümledeki "precisely" ve sabit bir SAATE (6 a.m.) bağlı program vurgusu olduğu için doğru cevap "on time"dır; "in time" burada yanlıştır çünkü kaçırılan bir fırsat ya da son an yetişme durumu söz konusu değildir.$u71a$, $u71b$"She finished wrapping the last gift just __________ before the guests started arriving at the door." "just... before" yapısı, bir şeyin olmasından HEMEN ÖNCE yetişmeyi anlatır, sabit bir saat değil bir SONUÇ vurgulanır → doğru cevap "in time"dır.$u71b$] WHERE id = '3fefa927-2f45-4878-a703-41ed55900621';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u72a$"You __________ lock the office tonight, or the night guard will report the breach to management." Cümlede açık bir UYARI ve olumsuz sonuç ("or the night guard will report") bulunduğu için doğru cevap "had better"dır; "would rather" burada bir tercih değil bir zorunluluk anlattığı için uygun değildir.$u72a$, $u72b$"I'd rather my sister __________ the truth before everyone found out from someone else." Tercih BAŞKA bir kişinin (my sister) eylemiyle ilgili olduğu için fiil past simple formunda gelir → doğru cevap "told"dur; "tell" ya da "will tell" bu yapıda kullanılmaz.$u72b$] WHERE id = '611cc281-bc26-43a8-8662-fb013072fb6e';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u73a$"They __________ (negotiate) the contract terms for nearly three weeks, and there's still no agreement." "for nearly three weeks" ile süregelen bir eylem ve bu eylemin hâlâ SONUÇLANMADIĞI ("still no agreement") anlatıldığı için doğru cevap "have been negotiating"tir; "have negotiated" kullanmak müzakerenin bittiği izlenimi verirdi.$u73a$, $u73b$"Your hands are covered in paint — __________ (you/paint) the fence again?" Eldeki boya lekesi (görünür bir KANIT) yakın zamanda sürdürülen bir eyleme işaret ettiği için doğru cevap "have you been painting"tir; "have you painted" sorusu işin TAMAMLANIP tamamlanmadığını sorar, mevcut lekenin nedenini değil.$u73b$] WHERE id = '82fe5ba0-13e0-45be-9ec9-242b7537a6e2';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u74a$"By the time the ambulance arrived, the injured man ___ (regain) consciousness." Bilincin geri kazanılması ambulansın varışından ÖNCE gerçekleştiği için doğru cevap "had regained"tır.$u74a$, $u74b$"As soon as she ___ (finish) her exam, she rushed outside to call her mother." İki eylem ART ARDA, sınavın bitmesinin HEMEN SONRASINDA gerçekleştiği için doğru cevap düz Past Simple'dır ("finished"), Past Perfect gerekmez çünkü sınavın bitmesi sınav bitmeden önce olan bir olay değil, dışarı koşmadan hemen önceki ardışık bir olaydır.$u74b$] WHERE id = 'a135dd9a-ca92-4a2a-ba36-92fd33040149';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u75a$"A mysterious stain had appeared __________ the ceiling of the old library." Tavan bir YÜZEY olarak düşünüldüğü için doğru cevap "on"dur; "in" ya da "at" burada yanlıştır.$u75a$, $u75b$"The peace treaty was signed __________ Geneva in the presence of several world leaders." Geneva bir şehir, yani bir HACİM/ALAN olarak düşünüldüğü için doğru cevap "in"dir; "at" kullanılsaydı şehir genel bir alan değil belirli tek bir nokta olarak ele alınırdı.$u75b$] WHERE id = 'cc4e9127-c8fe-44d1-b098-711c0e2c2432';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u76a$"I wish I __________ (not eat) so much at the party; I feel sick now." Geçmişte yapılmış, pişmanlık duyulan bir eylem anlatıldığı için doğru cevap "hadn't eaten"tır (past perfect); "didn't eat" burada yanlıştır çünkü dilek şimdiki bir durumdan değil geçmişteki bir eylemden duyulan pişmanlıktır.$u76a$, $u76b$"If only the neighbors __________ (turn down) that music; it's impossible to concentrate." Başkasının DEVAM EDEN davranışından duyulan rahatsızlık anlatıldığı için doğru cevap "would turn down"tır; "turned down" (past simple) burada yanlıştır çünkü bu yapı bir pişmanlığı değil bir ısrar/rahatsızlığı anlatır.$u76b$] WHERE id = 'e0308451-bc6b-48e5-9b8d-9e3a0d78ed8b';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u77a$"Every winter, we __________ our heating system __________ by a certified technician before the cold sets in." İş başkasına (teknisyene) yaptırıldığı için doğru yapı "have ... serviced"tir; "service" (V1) ya da "to service" bu kalıpta kullanılmaz.$u77a$, $u77b$"He was furious when he realized he __________ his wallet __________ while he was asleep on the train." Cüzdanın başına istenmeyen bir şekilde (hırsızlıkla) bir şey GELMESİ anlatıldığı için doğru yapı "had ... stolen"dır (geçmişte bir geçmiş); bu kalıp sadece bilinçli olarak yaptırılan işler için değil, başa gelen istenmeyen olaylar için de kullanılır.$u77b$] WHERE id = 'f8e72376-ebad-4130-94d1-291dff9e20ba';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u78a$"Thousands of jobs ___ as a result of the factory closures last year." Eylemi kimin yaptığı önemsiz, önemli olan işçilerin başına gelen şey olduğu için doğru cevap "were lost"tur; aktif çatıdaki "lost" (özne işleri kendisi kaybetmiş gibi okunur) burada yanlıştır.$u78a$, $u78b$"The ancient manuscript ___ by archaeologists during a recent excavation in the region." Cümlede EYLEMİ YAPAN ("by archaeologists") açıkça belirtildiği ve özne (manuscript) eylemi kendisi yapamayacağı için doğru cevap "was discovered"tur, aktif çatıdaki "discovered" yanlıştır.$u78b$] WHERE id = 'd9e204e0-755b-48a2-9417-55b55e5fa77f';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u79a$"Although the lock was rusted, the locksmith ___ open the door within minutes." Tek seferlik, belirli bir başarı anlatıldığı için doğru cevap "was able to"dur; "could" burada yanlıştır çünkü genel bir yeteneği değil, o anki özel bir başarıyı anlatır.$u79a$, $u79b$"As a child, my uncle ___ hold his breath underwater for almost two minutes." Burada geçmişte genel, sürekli bir yetenek anlatıldığı için doğru cevap "could"dur; "was able to" burada da kabul edilebilir olsa da, tekrarlanan/genel bir çocukluk becerisi anlatıldığı için "could" daha doğal ve beklenen cevaptır.$u79b$] WHERE id = 'b21c688a-8fb8-4768-a0f5-e3c1b588e638';

UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u80a$"The committee ___ (meet) every Thursday to review new applications." "every Thursday" düzenli tekrarlanan bir rutini işaret ettiği için doğru cevap "meets"tir (Present Simple); "is meeting" yanlıştır çünkü burada o anlık geçici bir durum değil, kalıcı bir program anlatılıyor.$u80a$, $u80b$"At the moment, no one ___ (know) exactly why the server crashed." "know" bir DURUM fiilidir (bilgi/anlayış bildirir) ve "at the moment" gibi genelde Present Continuous tetikleyen bir ifade olsa bile bu fiil -ing ALAMAZ → doğru cevap "knows"tur, "is knowing" hiçbir bağlamda kullanılmaz.$u80b$] WHERE id = '20a78810-94a2-4e1a-823d-7ed8239e75a9';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u81a$"The contract was __________ ambiguous to be approved without further legal review." Boşluktan sonra çıplak bir sıfat ("ambiguous") ve ardından "to be approved" (to + fiil) ile olumsuz bir sonuç bildirildiği için doğru cevap "too"dur; "so" da çıplak sıfattan önce gelebilir ama "so...that" tam cümleciği ister, burada "to+fiil" yapısı olduğu için "too" doğrudur.$u81a$, $u81b$"__________ many applicants submitted incomplete forms that the deadline had to be extended." Boşluktan sonra miktar belirteci "many" ve çoğul isim ("applicants") geldiği için doğru cevap yine "So"dur — bu, kuralın istisnasıdır: many/much/few/little ile birlikte de "so" kullanılır; "such" burada yanlıştır çünkü "such many" biçiminde bir kullanım İngilizce'de yoktur.$u81b$] WHERE id = '47621bc7-073e-4b23-973d-547e3b777a10';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u82a$"The company's CEO congratulated __________ on securing the biggest deal of the year, since he had led the negotiations personally." Özne (CEO) ile nesne AYNI kişi olduğu (kendini kutladı) anlatıldığı için doğru cevap "himself"tir; "him" kullanmak CEO'nun BAŞKA bir adamı kutladığı anlamına gelir ki bu, "he had led the negotiations personally" ifadesiyle çelişir.$u82a$, $u82b$"The software update installs __________ automatically whenever a new version is released, without requiring any action from the user." Özne (the software update) cansız bir nesnedir ve eylem KENDİ KENDİNE gerçekleştiği için doğru cevap "itself"tir; bu kullanımda zamir vurgu amaçlıdır ("kendi kendine") ve cümleden çıkarılsa da cümle gramatik olarak doğru kalır, sadece vurgu kaybolur.$u82b$] WHERE id = '613cf372-67df-4091-83ae-e222b39b1430';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u83a$"Would you like __________ milk in your coffee, or do you prefer it black?" Bu bir TEKLİF cümlesidir ve olumlu bir cevap beklenir, bu yüzden soru cümlesi olmasına rağmen doğru cevap "some"dur; normal soru kuralına göre "any" beklenirdi ama teklif/rica istisnası burada "some"u zorunlu kılar.$u83a$, $u83b$"There is __________ scientific evidence to support the claim that the supplement improves memory." Cümlede "not" ya da başka bir olumsuzluk sözcüğü yok, ama isimden ("scientific evidence") hemen önce gelen kelime cümleyi TEK BAŞINA olumsuz yapacak → doğru cevap "no"dur; "any" burada yanlıştır çünkü cümle zaten olumlu bir yapıdadır ("is") ve "any" tek başına cümleyi olumsuz yapamaz, mutlaka ayrı bir olumsuzluk sözcüğüyle birlikte kullanılır.$u83b$] WHERE id = '846bf314-b2e6-450d-be30-25797767de11';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u84a$"Halfway through the ceremony, the microphone suddenly __________ (switch off) and the speaker had to continue without it." Burada ANİ ve beklenmedik bir arıza anlatıldığı için ("suddenly") doğru cevap get passive "got switched off"tur; "was switched off" burada daha nötr/kasıtlı bir eylem izlenimi verir ve ânîliğin sürpriz etkisini taşımaz.$u84a$, $u84b$"In most European countries, primary education __________ (fund) entirely by the government." Resmi, genel-geçer bir politika/gerçek anlatıldığı için doğru cevap be passive "is funded"tur; "gets funded" burada günlük ve rastlantısal bir ton katar, akademik/resmi anlatımla uyuşmaz.$u84b$] WHERE id = 'a19e82af-6b2d-4137-a9b1-784e7cd1ab49';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u85a$"There was __________ much noise coming from the construction site that the teacher had to close the classroom windows." Boşluktan sonra miktar belirteci "much" ve sayılamayan bir isim ("noise") geldiği için doğru cevap yine "so"dur (many/much/few/little istisnası); "such" burada kullanılamaz çünkü "such much" diye bir yapı İngilizce'de yoktur.$u85a$, $u85b$"It was __________ disaster that the government had to declare a state of emergency." Boşluktan sonra sıfatsız, çıplak bir isim ("disaster") geldiği için doğru cevap "such a"dır; "so" burada yanlıştır çünkü "so" bir isim öbeğinden önce tek başına kullanılamaz, mutlaka bir sıfat veya zarfı doğrudan nitelemelidir.$u85b$] WHERE id = 'cdd5c4d4-6508-47c2-9e66-36252f23d6e9';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u86a$"Many graduate students are interested ___ (pursue) a career in renewable energy research." Boşluktan önce "interested in" sabit kalıbı var, edattan ("in") sonra fiil her zaman -ing alır → doğru cevap "in pursuing"dir; "to pursue" klasik bir tuzaktır çünkü "interested" sıfatından sonra "to+fiil" değil "in+-ing" gelir.$u86a$, $u86b$"After months of negotiations, both sides grew tired ___ (argue) over minor details and finally reached a compromise." Boşluktan önce "tired of" sabit kalıbı var → doğru cevap "of arguing"dir; "to argue" burada da yanlıştır çünkü "tired" sıfatından sonra sabit edat "of" gelir ve ardından mutlaka -ing kullanılır.$u86b$] WHERE id = 'e5701346-1262-4970-9761-f8cca07cf23a';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u87a$"The negotiators __________ (argue) for nearly four hours before they finally reached an agreement just before midnight." "for nearly four hours" süre ifadesi ve bu sürenin SONUNDA gerçekleşen bir olay ("reached an agreement") birlikte kullanıldığı için doğru cevap "had been arguing"dir.$u87a$, $u87b$"By the time the ambulance arrived, the paramedics realized that the patient __________ (lose) a significant amount of blood." Burada bir süreç değil, bir olayın ÖNCESİNDE tamamlanmış bir SONUÇ (kan kaybı miktarı) vurgulanıyor ve bir "for/since" süre ifadesi yok → doğru cevap düz Past Perfect "had lost"tur, "had been losing" değildir çünkü vurgulanan süren bir eylem değil, ulaşılmış bir sonuçtur.$u87b$] WHERE id = 'ff149e71-23ef-4074-841c-77fb2ad004f8';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u88a$"The book __________ won last year's literary prize has just been translated into fifteen languages." Boşluktan önce virgül YOK, bu cümlecik hangi kitaptan bahsedildiğini tanımladığı için defining'dir → doğru cevap "that/which"tir, "that" burada serbestçe kullanılabilir; cümlede virgül olsaydı "that" kesinlikle yanlış olurdu.$u88a$, $u88b$"Professor Aydın, __________ research on climate change has been cited worldwide, will give the keynote speech." Virgülle ayrılmış bir non-defining cümlecik ve iyelik anlamı (onun araştırması) taşıdığı için doğru cevap "whose"tur; bu yapıda da "that" kullanılamaz çünkü virgülden hemen sonra gelmiştir.$u88b$] WHERE id = '018a0797-2f2c-4927-9b3a-65aec2dda2de';
UPDATE public.exam_tactics SET examples_tr = examples_tr || ARRAY[$u89a$"The government introduced new regulations __________ reduce traffic congestion in the city center." Boşluktan sonra fiilin yalın hali ("reduce") geldiği için doğru cevap "in order to"dur; "so that" burada yanlıştır çünkü ardından özne+yüklem değil, doğrudan bir fiil kökü gelmiştir.$u89a$, $u89b$"The flight was cancelled __________ the airline could not find a replacement pilot in time." Boşluktan sonra özne+yüklem içeren tam bir cümlecik ("the airline could not find...") geldiği için doğru cevap "because"tir; "because of" yanlıştır çünkü ardından isim öbeği değil tam bir cümlecik gelmiştir.$u89b$] WHERE id = 'b4a94169-96da-4bb3-84d1-3ead6fb9de59';

